WITH base AS (SELECT id, store_id, quantity, last_restock, DATE_ADD(last_restock, 63) AS last_restock_plus_63d, ADD_MONTHS(last_restock, 12) AS last_restock_plus_months FROM inventory WHERE last_restock >= DATE '2024-02-12'), enriched AS (SELECT id, store_id, quantity, last_restock, last_restock_plus_63d, last_restock_plus_months, LAG(quantity, 1) OVER (PARTITION BY store_id ORDER BY quantity, id) AS prev_quantity, LAG(quantity, 1, 0) OVER (PARTITION BY store_id ORDER BY last_restock_plus_months, id) AS prev_quantity_2, AVG(quantity) OVER (ORDER BY quantity, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS quantity_avg_3 FROM base), valid AS (SELECT *, DATEDIFF(CURRENT_DATE(), last_restock) AS days_since_last_restock FROM enriched WHERE prev_quantity_2 != 238), grouped AS (SELECT DATE_TRUNC('YEAR', last_restock_plus_63d) AS year_start, DATE_TRUNC('WEEK', last_restock_plus_months) AS week_start, COUNT(DISTINCT id) AS distinct_ids, APPROX_PERCENTILE(quantity, 0.5) AS quantity_p50 FROM valid GROUP BY 1, 2 HAVING distinct_ids > 1) SELECT year_start, week_start, distinct_ids, quantity_p50 FROM grouped ORDER BY year_start NULLS LAST;
